// ---------- helpers ----------
const clamp = v => Math.max(0, Math.min(1, v));
const prog = (t, a, d) => clamp((t - a) / d);
const span = ([a, b]) => [a, b - a];
const lerp = (a, b, k) => a + (b - a) * k;
const lerpP = (p, q, k) => [lerp(p[0], q[0], k), lerp(p[1], q[1], k)];
const easeOutCubic = k => 1 - Math.pow(1 - k, 3);
const easeInOutCubic = k => k < .5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
const easeInOutSine = k => -(Math.cos(Math.PI * k) - 1) / 2;
const easeOutBack = (k, s = 1.9) => 1 + (s + 1) * Math.pow(k - 1, 3) + s * Math.pow(k - 1, 2);
const bump = k => Math.sin(Math.PI * clamp(k));
const around = (c, s, rot = 0, tx = 0, ty = 0) =>
  `translate(${c[0] + tx} ${c[1] + ty}) rotate(${rot}) scale(${s}) translate(${-c[0]} ${-c[1]})`;
let seed = 11;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;

function el(tag, attrs = {}, parent = svg) {
  const e = document.createElementNS(NS, tag);
  for (const k in attrs) e.setAttribute(k, attrs[k]);
  parent.appendChild(e);
  return e;
}

