  const len = p.getTotalLength();
  p.setAttribute('stroke-dasharray', len + 1);
  const anchors = [l.a, l.b].map(q => el('rect', { x: q[0] - 2.2, y: q[1] - 2.2, width: 4.4, height: 4.4, fill: '#fff', stroke: BLUE, 'stroke-width': 0.8, opacity: 0 }, sketchG));
